  function addMeta(name){
    var v=S.meta.length+1, now=new Date(), mo=['Jan','Feb','Mar','Apr','Mei','Jun','Jul','Agu','Sep','Okt','Nov','Des'];
    S.meta.push({v:v,file:'meta-'+Math.random().toString(16).slice(2,9)+'.tsv',when:now.getDate()+' '+mo[now.getMonth()]+' '+now.getFullYear()+', '+String(now.getHours()).padStart(2,'0')+'.'+String(now.getMinutes()).padStart(2,'0')+' WIB',rows:S0.length,name:name});
    S.metaSel=S.meta.length-1; render(); toast('success','Metadata Ditambahkan','Versi '+v+' dari '+name+' siap dipakai.');
  }

  /* ── events ── */
