    var t=e.target, a=t.closest('[data-a]'); if(!a) return; var k=a.dataset.a, i=+a.dataset.i;
    if(k==='rail'){S.rail=!S.rail; render();}
    else if(k==='guide'){e.preventDefault(); guideDlg();}
    else if(k==='runinfo') toast('success',run.name,run.kit+' kredit digunakan.');
